const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);function simple(n,d){const g=gcd(n,d);return n===0?'0':d/g===1?String(n/g).replace('-','−'):`${String(n/g).replace('-','−')}/${d/g}`}const storage={get(k){try{return localStorage.getItem('fondasi-multiply-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-multiply-'+k,v);return true}catch{return false}}};
function area(){let [a,b]=$('#first').value.split('/').map(Number),[c,d]=$('#second').value.split('/').map(Number);const original=`${a}/${b} dari ${c}/${d}`;if($('#swap').checked){[a,c]=[c,a];[b,d]=[d,b]}const n=a*c,den=b*d;$('#area-grid').style.gridTemplateColumns=`repeat(${d},1fr)`;$('#area-grid').style.gridTemplateRows=`repeat(${b},1fr)`;$('#area-grid').replaceChildren();for(let row=0;row<b;row++){for(let col=0;col<d;col++){const cell=document.createElement('span');cell.className='cell'+(row<a&&col<c?' selected':col<c?' horizontal':row<a?' vertical':'');cell.setAttribute('aria-hidden','true');$('#area-grid').append(cell)}}$('#area-grid').setAttribute('aria-label',`${b} baris dan ${d} kolom, dengan ${n} dari ${den} petak dipilih dalam kedua arah.`);$('#instruction').textContent=`Ambil ${c} dari ${d} kolom secara mendatar. Dari daerah itu, ambil ${a} dari ${b} baris secara tegak.`;const result=simple(n,den),raw=`${n}/${den}`;$('#equation').textContent=`${a}/${b} × ${c}/${d} = ${raw}${result!==raw?' = '+result:''}`;$('#feedback').textContent=`Seluruh bidang memiliki ${b} × ${d} = ${den} petak sama luas. Daerah yang dipilih dua kali terdiri dari ${a} × ${c} = ${n} petak. Jadi hasilnya ${result} dari satu utuh semula.`;$('#swap-note').textContent=$('#swap').checked?`Urutan ditukar dari ${original}. Susunan petak dapat berubah, tetapi nilai hasil tetap sama. Perkalian memiliki sifat pertukaran.`:'Coba tukar urutannya. Apakah jumlah bagian dari satu utuh yang diperoleh berubah?'}for(const id of ['#first','#second','#swap'])$(id).addEventListener('change',area);$('#reset').addEventListener('click',()=>{$('#first').value='2/3';$('#second').value='3/4';$('#swap').checked=false;area()});area();
for(let n=0;n<=2;n++){const x=30+n*270,line=document.createElementNS(ns,'line');for(const [k,v] of Object.entries({x1:x,x2:x,y1:66,y2:84,stroke:'#244d40'}))line.setAttribute(k,v);$('#scale-ticks').append(line);const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',120);t.setAttribute('text-anchor','middle');t.textContent=n;$('#scale-ticks').append(t)}function scale(){const [a,b]=$('#scale').value.split('/').map(Number),n=a*3,d=b*4,result=simple(n,d);$('#scale-equation').textContent=`${a}/${b} × 3/4 = ${n}/${d}${result!==`${n}/${d}`?' = '+result:''}`;$('#scale-dot').setAttribute('cx',30+270*n/d);$('#scale-feedback').textContent=a===0?'Mengalikan dengan 0 menghasilkan 0. Tidak ada bagian yang diambil.':a<b?'Faktor pengali positif dan kurang dari 1. Hasilnya lebih kecil daripada nilai awal 3/4.':a===b?'Faktor pengalinya 1. Nilai awal 3/4 tetap.':'Faktor pengalinya lebih dari 1. Hasilnya lebih besar daripada nilai awal 3/4. Misalnya, mengambil satu setengah kali berarti satu bagian semula ditambah setengah dari bagian itu.'}$('#scale').addEventListener('change',scale);scale();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='sixth'?'Tepat. Setiap sepertiga dibagi dua lagi, sehingga satu utuh dapat dibagi menjadi enam bagian sama besar. Temanmu menerima satu bagiannya.':v==='five'?'5/6 adalah hasil penjumlahan 1/2 + 1/3. Di sini kita mengambil setengah dari bagian sepertiga, sehingga hasilnya justru lebih kecil daripada sepertiga.':'Sepertiga adalah bagian yang kamu ambil pertama kali. Temanmu hanya menerima setengah dari bagian itu, sehingga menerima 1/6 dari batang semula.'});
const qs=[{t:'1/2 × 1/3 = …',n:1,d:6,h:'Bayangkan satu bagian sepertiga yang dibagi dua sama besar.',why:'Satu dari enam petak dipilih. Jadi 1/2 × 1/3 = 1/6.'},{t:'2/3 × 3/4 = …',n:1,d:2,h:'Kalikan pembilang, lalu penyebut. Sederhanakan bila ingin.',why:'(2 × 3)/(3 × 4) = 6/12 = 1/2.'},{t:'3/5 × 10 = …',n:6,d:1,h:'Bilangan 10 dapat ditulis 10/1. Atau bagi 10 menjadi lima kelompok, lalu ambil tiga kelompok.',why:'3/5 × 10/1 = 30/5 = 6.'},{t:'3/2 × 2/3 = …',n:1,d:1,h:'Kedua faktor dikalikan seperti biasa, meskipun satu faktor lebih dari satu.',why:'(3 × 2)/(2 × 3) = 6/6 = 1.'},{t:'0 × 3/4 = …',n:0,d:1,h:'Berapa bagian yang terambil jika mengambil nol kali?',why:'Tidak ada bagian yang diambil. Hasilnya 0.'},{t:'−1/2 × 1/3 = …',n:-1,d:6,h:'Negatif dikali positif menghasilkan negatif. Hitung nilai pecahannya.',why:'(−1 × 1)/(2 × 3) = −1/6.'}];function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}const solved=new Set();$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya 1/6" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const i=Number(f.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis pecahan seperti -1/6 atau bilangan bulat seperti 0. Penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Periksa operasi, faktor perkalian, dan tanda hasilnya. Buka petunjuk bila perlu.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari ${qs.length} latihan telah dijawab dengan tepat.`}));$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum dapat disimpan. Salin jika ingin menyimpannya.'});function completed(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')completed();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');completed();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu bisa kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan di peramban ini.'});
